// angular import
import { Component, output } from '@angular/core';

// project import
import { FriendsList } from 'src/app/fack-db/friends-list';
import { SharedModule } from 'src/app/theme/shared/shared.module';
import { FriendComponent } from './friend/friend.component';
import { DataFilterPipe } from 'src/app/theme/shared/filter/data-filter.pipe';

@Component({
  selector: 'app-chat-user-list',
  imports: [SharedModule, FriendComponent, DataFilterPipe],
  templateUrl: './chat-user-list.component.html',
  styleUrls: ['./chat-user-list.component.scss']
})
export class ChatUserListComponent {
  readonly ChatCollapse = output();
  readonly ChatToggle = output();
  // eslint-disable-next-line
  friendsList: any;
  searchFriends!: string;

  constructor() {
    this.friendsList = FriendsList.friends;
  }

  ChatOn() {
    this.ChatToggle.emit();
  }
}
<div class="h-list-header">
  <div class="input-group">
    <input type="text" id="search-friends" class="form-control" placeholder="Search Friend . . ." [(ngModel)]="searchFriends" />
  </div>
</div>
<div class="h-list-body">
  <a href="javascript:" class="h-close-text" (click)="this.ChatCollapse.emit()"><i class="feather icon-chevrons-right"></i></a>
  <div class="main-friend-cont scroll-div">
    <div class="main-friend-list">
      <ng-scrollbar style="height: calc(100vh - 85px)" visibility="hover">
        @for (friends of friendsList | dataFilter: searchFriends; track friends) {
          <app-friend (ChatOn)="ChatOn()" [friends]="friends" />
        }
      </ng-scrollbar>
    </div>
  </div>
</div>
